import { Dialog as BaseDialog } from '@base-ui/react/dialog';
import { ChevronLeft, ChevronRight, Play, X, ZoomIn, ZoomOut } from 'lucide-react';
import { useEffect, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { lightboxVariants } from './lightbox.variants';

export interface LightboxItem {
  src: string;
  /** Alternative text (images) or accessible name (videos). */
  alt: string;
  type?: 'image' | 'video';
  caption?: ReactNode;
  /** Thumbnail URL (defaults to `src` for images, `poster` for videos). */
  thumbnail?: string;
  poster?: string;
  /** WebVTT captions for videos. */
  captions?: string;
}

export interface LightboxLabels {
  title: string;
  close: string;
  previous: string;
  next: string;
  zoomIn: string;
  zoomOut: string;
  thumbnails: string;
  counter: (index: number, total: number) => string;
  status: (index: number, total: number, alt: string) => string;
  thumbnail: (index: number, alt: string) => string;
}

const defaultLabels: LightboxLabels = {
  title: 'Media viewer',
  close: 'Close viewer',
  previous: 'Previous',
  next: 'Next',
  zoomIn: 'Zoom in',
  zoomOut: 'Zoom out',
  thumbnails: 'Thumbnails',
  counter: (i, n) => `${i + 1} / ${n}`,
  status: (i, n, alt) => `${i + 1} of ${n}: ${alt}`,
  thumbnail: (i, alt) => `Show ${i + 1}: ${alt}`,
};

export interface LightboxProps {
  items: LightboxItem[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Wrap from the last item to the first. */
  loop?: boolean;
  showThumbnails?: boolean;
  /** Largest zoom factor (steps of 0.5). */
  maxZoom?: number;
  labels?: Partial<LightboxLabels>;
  container?: BaseDialog.Portal.Props['container'];
}

/**
 * Full-screen image and video viewer on Base UI Dialog: previous / next, zoom with a scrollable
 * stage, captions and a thumbnail strip. Arrow keys move (mirrored in RTL), +/−/0 zoom, Escape
 * closes and focus returns to whatever opened it.
 */
export function Lightbox({
  items,
  open,
  defaultOpen = false,
  onOpenChange,
  index,
  defaultIndex = 0,
  onIndexChange,
  loop = false,
  showThumbnails = true,
  maxZoom = 4,
  labels: labelsProp,
  container,
}: LightboxProps) {
  const labels = { ...defaultLabels, ...labelsProp };
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const [innerIndex, setInnerIndex] = useState(defaultIndex);
  const [zoomState, setZoomState] = useState({ at: -1, zoom: 1 });
  const thumbsRef = useRef<HTMLDivElement | null>(null);
  const isOpen = open ?? innerOpen;
  const total = items.length;
  const current = Math.min(Math.max(index ?? innerIndex, 0), Math.max(total - 1, 0));
  const item = items[current];
  const zoom = zoomState.at === current ? zoomState.zoom : 1;
  const isVideo = item?.type === 'video';
  const s = lightboxVariants();

  const setOpen = (next: boolean) => {
    setInnerOpen(next);
    onOpenChange?.(next);
  };
  const go = (i: number) => {
    const next = loop ? (i + total) % total : Math.min(Math.max(i, 0), total - 1);
    if (next === current || total === 0) return;
    setInnerIndex(next);
    onIndexChange?.(next);
  };
  const setZoom = (z: number) => setZoomState({ at: current, zoom: Math.min(Math.max(z, 1), maxZoom) });

  useEffect(() => {
    if (!isOpen) return;
    thumbsRef.current?.querySelector('[aria-current="true"]')?.scrollIntoView?.({ block: 'nearest', inline: 'center' });
  }, [isOpen, current]);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).tagName === 'VIDEO') return;
    const rtl = getComputedStyle(e.currentTarget).direction === 'rtl';
    const actions: Record<string, () => void> = {
      [rtl ? 'ArrowLeft' : 'ArrowRight']: () => go(current + 1),
      [rtl ? 'ArrowRight' : 'ArrowLeft']: () => go(current - 1),
      Home: () => go(0),
      End: () => go(total - 1),
      '+': () => setZoom(zoom + 0.5),
      '=': () => setZoom(zoom + 0.5),
      '-': () => setZoom(zoom - 0.5),
      '0': () => setZoom(1),
    };
    const action = actions[e.key];
    if (!action || e.altKey || e.ctrlKey || e.metaKey) return;
    if (isVideo && e.key.length === 1) return;
    e.preventDefault();
    action();
  };

  const atStart = !loop && current === 0;
  const atEnd = !loop && current >= total - 1;

  return (
    <BaseDialog.Root open={isOpen} onOpenChange={(next) => setOpen(next)}>
      <BaseDialog.Portal container={container}>
        <BaseDialog.Backdrop className={s.backdrop()} />
        <BaseDialog.Popup className={s.popup()} onKeyDown={onKeyDown}>
          <BaseDialog.Title className="sr-only">{labels.title}</BaseDialog.Title>
          <div className={s.bar()}>
            <span className={s.counter()} aria-hidden>
              {labels.counter(current, total)}
            </span>
            {!isVideo && (
              <>
                <button type="button" className={s.control()} aria-label={labels.zoomOut} disabled={zoom <= 1} onClick={() => setZoom(zoom - 0.5)}>
                  <ZoomOut size={16} aria-hidden />
                </button>
                <span className={s.zoomValue()} aria-hidden>
                  {Math.round(zoom * 100)}%
                </span>
                <button type="button" className={s.control()} aria-label={labels.zoomIn} disabled={zoom >= maxZoom} onClick={() => setZoom(zoom + 0.5)}>
                  <ZoomIn size={16} aria-hidden />
                </button>
              </>
            )}
            <BaseDialog.Close className={s.control()} aria-label={labels.close}>
              <X size={17} aria-hidden />
            </BaseDialog.Close>
          </div>
          <div className={s.stageWrap()}>
            {total > 1 && (
              <button type="button" className={cn(s.nav(), s.prev())} aria-label={labels.previous} disabled={atStart} onClick={() => go(current - 1)}>
                <ChevronLeft size={18} aria-hidden className="rtl:-scale-x-100" />
              </button>
            )}
            <figure className="m-0 flex min-h-0 min-w-0 flex-1 flex-col">
              <div className={s.stage()} onDoubleClick={() => !isVideo && setZoom(zoom > 1 ? 1 : 2)}>
                {item &&
                  (isVideo ? (
                    <video key={item.src} src={item.src} poster={item.poster} controls aria-label={item.alt} className={s.media()} style={{ maxHeight: '100%' }}>
                      {item.captions && <track kind="captions" src={item.captions} default />}
                    </video>
                  ) : (
                    <img
                      key={item.src}
                      src={item.src}
                      alt={item.alt}
                      draggable={false}
                      className={s.media()}
                      style={{ height: zoom > 1 ? `${zoom * 100}%` : undefined, maxHeight: zoom > 1 ? 'none' : '100%', maxWidth: zoom > 1 ? 'none' : '100%' }}
                    />
                  ))}
              </div>
              {item?.caption != null && <figcaption className={s.caption()}>{item.caption}</figcaption>}
            </figure>
            {total > 1 && (
              <button type="button" className={cn(s.nav(), s.next())} aria-label={labels.next} disabled={atEnd} onClick={() => go(current + 1)}>
                <ChevronRight size={18} aria-hidden className="rtl:-scale-x-100" />
              </button>
            )}
          </div>
          {showThumbnails && total > 1 && (
            <div ref={thumbsRef} role="group" aria-label={labels.thumbnails} className={s.thumbs()}>
              {items.map((it, i) => {
                const thumb = it.thumbnail ?? (it.type === 'video' ? it.poster : it.src);
                return (
                  <button key={`${it.src}-${i}`} type="button" className={s.thumb()} aria-label={labels.thumbnail(i, it.alt)} aria-current={i === current} onClick={() => go(i)}>
                    {thumb && <img src={thumb} alt="" className={s.thumbImg()} />}
                    {it.type === 'video' && (
                      <span className={s.thumbBadge()} aria-hidden>
                        <Play size={14} />
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          )}
          <span role="status" className="sr-only">
            {item ? labels.status(current, total, item.alt) : ''}
          </span>
        </BaseDialog.Popup>
      </BaseDialog.Portal>
    </BaseDialog.Root>
  );
}

export { Lightbox, type LightboxProps, type LightboxItem, type LightboxLabels } from './Lightbox';
export { lightboxVariants, type LightboxVariantProps } from './lightbox.variants';
export { doc as lightboxDoc } from './Lightbox.doc';

import { tv, type VariantProps } from '../../utils/tv';

const control = [
  'grid size-9 shrink-0 place-items-center rounded-lg text-muted-foreground transition-colors motion-reduce:transition-none',
  'hover:bg-secondary/70 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
  'disabled:pointer-events-none disabled:opacity-40',
];

export const lightboxVariants = tv({
  slots: {
    backdrop: 'fixed inset-0 z-50 bg-background/95 transition-opacity duration-200 motion-reduce:transition-none data-starting-style:opacity-0 data-ending-style:opacity-0',
    popup: [
      'fixed inset-0 z-50 flex flex-col text-foreground outline-none',
      'transition-opacity duration-200 motion-reduce:transition-none data-starting-style:opacity-0 data-ending-style:opacity-0',
    ],
    bar: 'flex shrink-0 items-center gap-1 border-b border-border/60 bg-chrome px-3 py-2',
    counter: 'me-auto font-mono text-[12px] text-muted-foreground tabular-nums',
    zoomValue: 'w-12 text-center font-mono text-[11.5px] text-muted-foreground tabular-nums',
    control,
    stageWrap: 'relative flex min-h-0 flex-1 items-stretch',
    stage: 'grid min-h-0 min-w-0 flex-1 place-items-center overflow-auto p-4 sm:px-16',
    media: 'w-auto max-w-full rounded-md object-contain shadow-md select-none',
    nav: [
      'absolute top-1/2 z-10 grid size-10 -translate-y-1/2 place-items-center rounded-full border border-border bg-card text-foreground shadow-sm transition-colors',
      'hover:bg-secondary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring disabled:pointer-events-none disabled:opacity-40',
    ],
    prev: 'start-3',
    next: 'end-3',
    caption: 'shrink-0 px-4 pt-1 pb-3 text-center text-[13px] text-muted-foreground text-pretty',
    thumbs: 'flex shrink-0 justify-center gap-2 overflow-x-auto border-t border-border/60 bg-chrome px-3 py-2.5',
    thumb: [
      'relative size-14 shrink-0 overflow-hidden rounded-md border border-border opacity-60 transition-opacity motion-reduce:transition-none',
      'hover:opacity-100 aria-[current=true]:border-primary aria-[current=true]:opacity-100',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
    thumbImg: 'size-full object-cover',
    thumbBadge: 'absolute inset-0 grid place-items-center bg-background/40 text-foreground',
  },
});

export type LightboxVariantProps = VariantProps<typeof lightboxVariants>;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
